    general = {
        gaps_in          = 5,
        gaps_out         = 12,
        border_size      = 2,
        col = {
            active_border   = { colors = {"rgba(7aa2f7ff)", "rgba(bb9af7ff)"}, angle = 45 },
            inactive_border = "rgba(414868aa)",
        },
        layout           = "dwindle",
        resize_on_border = false,
    },
})
