    decoration = {
        rounding         = 10,
        rounding_power   = 2.0,
        active_opacity   = 1.0,
        inactive_opacity = 0.92,
        dim_inactive     = false,
        dim_strength     = 0.3,
        blur = {
            enabled        = true,
            size           = 6,
            passes         = 2,
