})
hl.config({
    animations = {
        enabled = true,
    },
})
hl.config({
    dwindle = {
        preserve_split = true,
        force_split    = 0,
        smart_split    = false,
    },
})
hl.config({
    master = {
        new_status  = "master",
        mfact       = 0.55,
        orientation = "left",
    },
})
hl.config({
    input = {
        kb_layout          = "de",
        kb_variant         = "",
        kb_options         = "",
        numlock_by_default = false,
        repeat_rate        = 25,
        repeat_delay       = 600,
        follow_mouse       = 1,
        sensitivity        = 0.0,
        accel_profile      = "",
        left_handed        = false,
        natural_scroll     = false,
        touchpad = {
            natural_scroll       = false,
            disable_while_typing = true,
            scroll_factor        = 1.0,
        },
    },
})
hl.config({
    cursor = {
        inactive_timeout  = 0.0,
        hide_on_key_press = false,
    },
})
hl.config({
    misc = {
        disable_hyprland_logo    = true,
        disable_splash_rendering = true,
        force_default_wallpaper  = 0,
        background_color         = "rgba(111111ff)",
        focus_on_activate        = false,
        enable_swallow           = false,
        swallow_regex            = "^(kitty|foot|Alacritty)$",
        middle_click_paste       = true,
        mouse_move_enables_dpms  = true,
        key_press_enables_dpms   = true,
    },
})

hl.curve("hs_curve", { type = "bezier", points = { {0.23, 1.0}, {0.32, 1.0} } })
hl.animation({ leaf = "windowsIn", enabled = true, speed = 4.1, bezier = "hs_curve", style = "popin 80%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 1.5, bezier = "hs_curve", style = "popin 80%" })
