hl.animation({ leaf = "border", enabled = true, speed = 5.4, bezier = "hs_curve" })
hl.animation({ leaf = "fade", enabled = true, speed = 3.0, bezier = "hs_curve" })
hl.animation({ leaf = "layers", enabled = true, speed = 3.8, bezier = "hs_curve" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 3.0, bezier = "hs_curve", style = "slide" })

