        "format": "CPU {usage}%",
        "interval": 5,
        "tooltip": false
    },
    "memory": {
        "format": "RAM {percentage}%",
        "interval": 5,
        "tooltip": false
    },
    "disk": {
        "format": "Disk {percentage_used}%",
        "path": "/",
        "interval": 30,
        "tooltip": false
    },
    "temperature": {
        "format": "{temperatureC}°C",
        "interval": 5,
        "tooltip": false
