            "default": [
                "",
                "",
                ""
            ]
        },
        "scroll-step": 5,
        "on-click": "pavucontrol",
        "tooltip": false
    },
    "backlight": {
        "format": "Hell {percent}%",
        "format-icons": [
            ""
        ],
        "tooltip": false
    },
    "network": {
        "format-wifi": "{ipaddr}",
        "format-ethernet": "{ipaddr}",
        "format-disconnected": "Offline",
        "tooltip-format": "{ifname} · {ipaddr}",
        "tooltip": false
    },
    "bluetooth": {
        "format": "BT",
        "format-connected": "BT {num_connections}",
        "tooltip": false
    },
    "battery": {
        "format": "Bat {capacity}%",
        "format-icons": [
            "",
            "",
            "",
            "",
            ""
        ],
        "format-charging": "{capacity}%",
        "states": {
            "warning": 30,
            "critical": 15
        },
        "tooltip": false
    },
    "tray": {
        "spacing": 8,
        "icon-size": 16,
        "tooltip": false
    },
    "custom/power": {
        "format": "Power",
        "on-click": "wlogout",
        "tooltip": false,
        "justify": "center"
    }
}

